import sys
import os
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_settings(settings_path):
    try:
        tree = ET.parse(settings_path)
        root = tree.getroot()
    except (IOError, ET.ParseError) as e:
        print(f"Error reading settings file: {settings_path}", file=sys.stderr)
        sys.exit(1)

    if root.tag != 'inventory':
        print(f"Error: settings file must have root element 'inventory': {settings_path}", file=sys.stderr)
        sys.exit(1)

    output_path = None
    log_path = None
    rules = []
    default_category = None

    for child in root:
        if child.tag == 'output' and 'path' in child.attrib:
            output_path = child.attrib['path']
        elif child.tag == 'log' and 'path' in child.attrib:
            log_path = child.attrib['path']
        elif child.tag == 'rule' and 'extension' in child.attrib and 'category' in child.attrib:
            rules.append((child.attrib['extension'], child.attrib['category']))
        elif child.tag == 'default' and 'category' in child.attrib:
            default_category = child.attrib['category']

    if not output_path or not log_path:
        print(f"Error: settings file must contain both <output> and <log> elements: {settings_path}", file=sys.stderr)
        sys.exit(1)

    return output_path, log_path, rules, default_category

def get_category(extension, rules, default_category):
    for ext, category in rules:
        if ext == extension:
            return category
    return default_category if default_category else 'unclassified'

def process_paths(settings_path, paths):
    output_path, log_path, rules, default_category = parse_settings(settings_path)

    with open(output_path, 'w') as out_file, open(log_path, 'a') as log_file:
        for path_str in paths:
            path = Path(path_str).resolve()
            stripped_path = path_str.strip()
            if not stripped_path:
                continue

            # Extract extension
            last_slash = stripped_path.rfind('/')
            segment = stripped_path[last_slash + 1:] if last_slash != -1 else stripped_path
            extension = segment.rsplit('.', 1)[-1] if '.' in segment else ''

            # Determine category
            category = get_category(extension, rules, default_category)

            # Check file existence
            if path.exists():
                out_file.write(f"{path_str}\t{category}\n")
                log_file.write(f"INFO: classified {path_str} as {category}\n")
            else:
                log_file.write(f"ERROR: missing {path_str}\n")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python inventory.py settings.xml", file=sys.stderr)
        sys.exit(1)

    settings_path = sys.argv[1]
    paths = sys.stdin.read().splitlines()
    process_paths(settings_path, paths)

