import sys
import os
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_settings(settings_path):
    try:
        tree = ET.parse(settings_path)
        root = tree.getroot()
    except (ET.ParseError, IOError) as e:
        print(f"Error: {settings_path}", file=sys.stderr)
        sys.exit(1)

    if root.tag != 'inventory':
        print(f"Error: {settings_path} is not a valid inventory settings file", file=sys.stderr)
        sys.exit(1)

    output_path = None
    log_path = None
    rules = []
    default_category = None

    for child in root:
        if child.tag == 'output' and 'path' in child.attrib:
            output_path = child.attrib['path']
        elif child.tag == 'log' and 'path' in child.attrib:
            log_path = child.attrib['path']
        elif child.tag == 'rule' and 'extension' in child.attrib and 'category' in child.attrib:
            rules.append((child.attrib['extension'], child.attrib['category']))
        elif child.tag == 'default' and 'category' in child.attrib:
            default_category = child.attrib['category']

    if output_path is None or log_path is None:
        print(f"Error: {settings_path} is missing required elements", file=sys.stderr)
        sys.exit(1)

    return output_path, log_path, rules, default_category

def get_category(path_segment, rules, default_category):
    for ext, category in rules:
        if ext == path_segment:
            return category
    return default_category if default_category is not None else 'unclassified'

def process_paths(settings_path, output_path, log_path, rules, default_category):
    output_file = open(output_path, 'a')
    log_file = open(log_path, 'a')

    for line in sys.stdin:
        path = line.strip()
        if not path:
            continue

        path_parts = path.split('/')[-1].split('.')
        if len(path_parts) > 1:
            extension = '.' + path_parts[-1]
        else:
            extension = ''

        category = get_category(extension, rules, default_category)

        if os.path.exists(path):
            output_file.write(f"{path}\t{category}\n")
            log_file.write(f"INFO: classified {path} as {category}\n")
        else:
            log_file.write(f"ERROR: missing {path}\n")

    output_file.close()
    log_file.close()

def main():
    if len(sys.argv) != 2:
        print("Usage: python inventory.py settings.xml", file=sys.stderr)
        sys.exit(1)

    settings_path = sys.argv[1]
    output_path, log_path, rules, default_category = parse_settings(settings_path)
    process_paths(settings_path, output_path, log_path, rules, default_category)

if __name__ == "__main__":
    main()
